import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa v2.0 x-thread (日本語)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v2.0/x-thread-ja.md","filePath":"announcements/v2.0/x-thread-ja.md"}'),o={name:"announcements/v2.0/x-thread-ja.md"};function i(d,e,s,c,p,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="kiwa-v2-0-x-thread-日本語" tabindex="-1">kiwa v2.0 x-thread (日本語) <a class="header-anchor" href="#kiwa-v2-0-x-thread-日本語" aria-label="Permalink to &quot;kiwa v2.0 x-thread (日本語)&quot;">​</a></h1><h2 id="tweet-1" tabindex="-1">Tweet 1 <a class="header-anchor" href="#tweet-1" aria-label="Permalink to &quot;Tweet 1&quot;">​</a></h2><p>kiwa v2.0 リリース — <strong>brand shortening rename</strong>。 全 41 kiwa package の scope を <code>@kiwa-test/*</code> から <code>@kiwa-lab/*</code> に一斉変更、 全 package を v2.0.0 に major bump。 API 変更 0、 shape 契約 preserving、 backward compat 絶対維持 (deprecated re-export 6 ヶ月 window、 2026-07-08 → 2027-01-08)。</p><h2 id="tweet-2" tabindex="-1">Tweet 2 <a class="header-anchor" href="#tweet-2" aria-label="Permalink to &quot;Tweet 2&quot;">​</a></h2><p>pure rename milestone、 5 PR 例外拡張 (rename milestone のみ 4 PR rhythm 一時休止、 v2.1 以降 復帰)。 1424 file + 900+ 参照 の 一斉 rename、 packages + workspace internal dep + docs + dogfood + tests 全 追随、 semantic 変更 0。</p><h2 id="tweet-3" tabindex="-1">Tweet 3 <a class="header-anchor" href="#tweet-3" aria-label="Permalink to &quot;Tweet 3&quot;">​</a></h2><p>新規 consumer は <code>pnpm add -D @kiwa-lab/core@^2.0</code>。 既存 consumer は 即時 sed 置換 or 6 ヶ月 grace period (@kiwa-test/* v2.0.0 は deprecated shim として @kiwa-lab/* を re-export、 console.warn 出力)。</p><h2 id="tweet-4" tabindex="-1">Tweet 4 <a class="header-anchor" href="#tweet-4" aria-label="Permalink to &quot;Tweet 4&quot;">​</a></h2><p>rename 理由 = <code>@kiwa-test/*</code> は 「テスト特化」 を暗示、 v2.0+ 拡張時に mismatch。 <code>@kiwa-lab/*</code> は 短縮 + brand 統一。 45 milestone streak + depth-5 3 例目確定 + depth-6 2 例目確定 candidate の compound 資産 は kiwa brand で 継承。</p><p>Lean 形式検証 統合は 別ライブラリ で 独立展開予定、 kiwa 本体 は testing 特化 維持。</p><p>migration: <a href="https://cardene777.github.io/kiwa/migrations/v2.0-rename-plan" target="_blank" rel="noreferrer">https://cardene777.github.io/kiwa/migrations/v2.0-rename-plan</a></p><p>#kiwa #v2 #rename #testing #vitest</p>',12)])])}const w=a(o,[["render",i]]);export{m as __pageData,w as default};
